    enum FulfillmentType { SHIP_TO_HOME, STORE_PICKUP }
    enum Availability    { IN_STOCK, PRE_ORDER, BACKORDERED }

    record Address(String id) {}
    record Warehouse(String id) {}

    record LineItem(
            String productId,
            int quantity,
            FulfillmentType fulfillmentType,
            Address deliveryAddress,
            Availability availability,
            LocalDate availableFrom,   // null when IN_STOCK
            String companionGroupId    // null when no companion constraint
    ) {
        static LineItem inStock(String productId, int qty, Address addr) {
            return new LineItem(productId, qty, FulfillmentType.SHIP_TO_HOME,
                    addr, Availability.IN_STOCK, null, null);
        }
        static LineItem pickup(String productId, int qty, Address store) {
            return new LineItem(productId, qty, FulfillmentType.STORE_PICKUP,
                    store, Availability.IN_STOCK, null, null);
        }
        LineItem withAvailability(Availability av, LocalDate from) {
            return new LineItem(productId, quantity, fulfillmentType,
                    deliveryAddress, av, from, companionGroupId);
        }
        LineItem withCompanionGroup(String group) {
            return new LineItem(productId, quantity, fulfillmentType,
                    deliveryAddress, availability, availableFrom, group);
        }
    }

    /** Stock level for one product at one warehouse. */
    record Stock(Warehouse warehouse, String productId, int quantity) {}

    record Order(String id, List<LineItem> items) {}

    record Shipment(
            Warehouse source,
            List<LineItem> items,
            FulfillmentType fulfillmentType,
            Address destination
    ) {}

