    private Shipment shipmentFor(List<Shipment> shipments, String productId) {
        return shipments.stream()
                .filter(s -> s.items().stream()
                        .anyMatch(i -> i.productId().equals(productId)))
                .findFirst()
                .orElseThrow(() -> new AssertionError(
                        "No shipment found for product " + productId));
    }

    private Set<Warehouse> sources(List<Shipment> shipments) {
        return Set.copyOf(shipments.stream().map(Shipment::source).toList());
    }
